@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustomDateTimePicker(
    label: String,
    value: String,
    onDateTimeSelected: (String) -> Unit,
    modifier: Modifier = Modifier,
    dateTimeFormat: String = "dd/MM/yyyy HH:mm"
) {
    var showDatePicker by remember { mutableStateOf(false) }
    var showTimePicker by remember { mutableStateOf(false) }

    // Parse existing value or use current date/time
    val calendar = remember(value) {
        if (value.isNotBlank()) {
            try {
                val formatter = DateTimeFormatter.ofPattern(dateTimeFormat)
                val dateTime = LocalDateTime.parse(value, formatter)
                Calendar.getInstance().apply {
                    set(Calendar.YEAR, dateTime.year)
                    set(Calendar.MONTH, dateTime.monthValue - 1)
                    set(Calendar.DAY_OF_MONTH, dateTime.dayOfMonth)
                    set(Calendar.HOUR_OF_DAY, dateTime.hour)
                    set(Calendar.MINUTE, dateTime.minute)
                }
            } catch (_: Exception) {
                Calendar.getInstance()
            }
        } else {
            Calendar.getInstance()
        }
    }

    var selectedDate by remember { mutableStateOf(calendar.timeInMillis) }
    var selectedHour by remember { mutableStateOf(calendar.get(Calendar.HOUR_OF_DAY)) }
    var selectedMinute by remember { mutableStateOf(calendar.get(Calendar.MINUTE)) }

    val displayValue = remember(selectedDate, selectedHour, selectedMinute) {
        val cal = Calendar.getInstance().apply {
            timeInMillis = selectedDate
            set(Calendar.HOUR_OF_DAY, selectedHour)
            set(Calendar.MINUTE, selectedMinute)
        }
        SimpleDateFormat(dateTimeFormat, Locale.getDefault()).format(cal.time)
    }

    OutlinedTextField(
        value = displayValue,
        onValueChange = {},
        label = { Text(label) },
        readOnly = true,
        modifier = modifier.fillMaxWidth(),
        shape = RoundedCornerShape(8.dp),
        colors = OutlinedTextFieldDefaults.colors(
            focusedBorderColor = Blue1,
            unfocusedBorderColor = Color.Gray.copy(alpha = 0.5f),
            disabledBorderColor = Color.Gray.copy(alpha = 0.5f),
            disabledTextColor = Color.Black
        ),
        trailingIcon = {
            Row {
                IconButton(onClick = { showDatePicker = true }) {
                    Icon(
                        imageVector = Icons.Default.CalendarToday,
                        contentDescription = "Chọn ngày",
                        tint = Blue1
                    )
                }
                IconButton(onClick = { showTimePicker = true }) {
                    Icon(
                        imageVector = Icons.Default.Schedule,
                        contentDescription = "Chọn giờ",
                        tint = Blue1
                    )
                }
            }
        }
    )

    // Date Picker Dialog
    if (showDatePicker) {
        val datePickerState = rememberDatePickerState(
            initialSelectedDateMillis = selectedDate
        )

        DatePickerDialog(
            onDismissRequest = { showDatePicker = false },
            confirmButton = {
                Button(
                    onClick = {
                        datePickerState.selectedDateMillis?.let { millis ->
                            selectedDate = millis
                            val cal = Calendar.getInstance().apply {
                                timeInMillis = millis
                                set(Calendar.HOUR_OF_DAY, selectedHour)
                                set(Calendar.MINUTE, selectedMinute)
                            }
                            val formattedDateTime = SimpleDateFormat(dateTimeFormat, Locale.getDefault()).format(cal.time)
                            onDateTimeSelected(formattedDateTime)
                        }
                        showDatePicker = false
                    },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Blue1
                    )
                ) {
                    Text("Xác nhận")
                }
            },
            dismissButton = {
                OutlinedButton(onClick = { showDatePicker = false }) {
                    Text("Hủy", color = Blue1)
                }
            }
        ) {
            DatePicker(state = datePickerState)
        }
    }

    // Time Picker Dialog
    if (showTimePicker) {
        TimePickerDialog(
            initialHour = selectedHour,
            initialMinute = selectedMinute,
            onDismiss = { showTimePicker = false },
            onConfirm = { hour, minute ->
                selectedHour = hour
                selectedMinute = minute
                val cal = Calendar.getInstance().apply {
                    timeInMillis = selectedDate
                    set(Calendar.HOUR_OF_DAY, hour)
                    set(Calendar.MINUTE, minute)
                }
                val formattedDateTime = SimpleDateFormat(dateTimeFormat, Locale.getDefault()).format(cal.time)
                onDateTimeSelected(formattedDateTime)
                showTimePicker = false
            }
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TimePickerDialog(
    initialHour: Int,
    initialMinute: Int,
    onDismiss: () -> Unit,
    onConfirm: (hour: Int, minute: Int) -> Unit
) {
    val timePickerState = rememberTimePickerState(
        initialHour = initialHour,
        initialMinute = initialMinute,
        is24Hour = true
    )

    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(
            usePlatformDefaultWidth = false
        )
    ) {
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            shape = RoundedCornerShape(16.dp),
            colors = CardDefaults.cardColors(
                containerColor = Color.White
            )
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    text = "Chọn giờ",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    color = Blue1,
                    modifier = Modifier.padding(bottom = 16.dp)
                )

                TimePicker(
                    state = timePickerState,
                    colors = TimePickerDefaults.colors(
                        clockDialColor = Blue1.copy(alpha = 0.1f),
                        selectorColor = Blue1,
                        clockDialSelectedContentColor = Color.White,
                        clockDialUnselectedContentColor = Blue1,
                        timeSelectorSelectedContainerColor = Blue1,
                        timeSelectorUnselectedContainerColor = Blue1.copy(alpha = 0.1f),
                        timeSelectorSelectedContentColor = Color.White,
                        timeSelectorUnselectedContentColor = Blue1
                    )
                )

                Spacer(modifier = Modifier.height(16.dp))

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.End
                ) {
                    OutlinedButton(
                        onClick = onDismiss,
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = Blue1
                        )
                    ) {
                        Text("Hủy")
                    }

                    Spacer(modifier = Modifier.width(8.dp))

                    Button(
                        onClick = {
                            onConfirm(timePickerState.hour, timePickerState.minute)
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = Blue1
                        )
                    ) {
                        Text("Xác nhận")
                    }
                }
            }
        }
    }
}

